#include<bits/stdc++.h>

constexpr auto MAXN = 5000 + 50;

struct Edge {
	int fr, to, residual, cost;
};
std::vector<Edge>edges; std::vector<int> G[MAXN];
int s, t, maxFlow, minCost;
int last[MAXN], flow[MAXN], dis[MAXN];
bool inQueue[MAXN];

bool SPFA() {
	memset(inQueue, false, sizeof(inQueue)); std::fill(dis, dis + MAXN, INT_MAX);
	std::queue<int> que; que.push(s); inQueue[s] = true; 
	flow[s] = INT_MAX; last[s] = 0; dis[s] = 0;

	int nowAt;
	while (!que.empty()) {
		nowAt = que.front(); que.pop(); inQueue[nowAt] = false;
		for (int i = 0; i < G[nowAt].size(); i++) {
			Edge& it = edges[G[nowAt][i]];
			if (it.residual > 0 && dis[it.to] > dis[nowAt] + it.cost) {
				dis[it.to] = dis[nowAt] + it.cost;
				last[it.to] = G[nowAt][i];
				flow[it.to] = std::min(flow[nowAt], it.residual);
				if (!inQueue[it.to]) { inQueue[it.to] = true; que.push(it.to); }
			}
		}
	}
	if (dis[t] == INT_MAX)return false;

	maxFlow += flow[t]; minCost += dis[t] * flow[t];
	nowAt = t;
	while (nowAt != s) {
		edges[last[nowAt]].residual -= flow[t];
		edges[last[nowAt] ^ 1].residual += flow[t];
		nowAt = edges[last[nowAt]].fr;
	}
    return true;
}

void MCMF() {
	maxFlow = 0; minCost = 0;
	while (SPFA());
}

signed main()
{
	int fr, to, cost, flow;
	int totNode, totEdges;

	scanf("%d%d%d%d", &totNode, &totEdges, &s, &t);
	for (int i = 0; i < totEdges; i++) {
		scanf("%d%d%d%d", &fr, &to, &flow, &cost);
		G[fr].push_back(edges.size()); edges.push_back({ fr,to,flow,cost });
		G[to].push_back(edges.size()); edges.push_back({ to,fr,0,-cost });
	}
    MCMF();

	printf("%d %d\n", maxFlow, minCost);

	//system("pause");
	return 0;
}

正切半角公式又称万能公式，这一组公式有四个功能：

将角统一为\frac{\alpha }{2}；

将函数名称统一为\tan；

任意实数都可以\tan \frac{\alpha }{2}的形式表达，可用正切函数换元。

在某些积分中，可以将含有三角函数的积分变为有理分式的积分。

因此，这组公式被称为以切表弦公式，简称以切表弦。它们是由二倍角公式求得的。

\sin \alpha = \frac{{2\tan \frac{\alpha }{2}}}{{1 + \tan ^2 \frac{\alpha }{2}}}

\cos \alpha = \frac{{1 - \tan ^2 \frac{\alpha }{2}}}{{1 + \tan ^2 \frac{\alpha }{2}}}

\tan \alpha = \frac{{2\tan \frac{\alpha }{2}}}{{1 - \tan ^2 \frac{\alpha }{2}}}

\cot \alpha = \frac{{1 - \tan ^2 \frac{\alpha }{2}}}{{2\tan \frac{\alpha }{2}}}

\sec \alpha = \frac{{1 + \tan ^2 \frac{\alpha }{2}}}{{1 - \tan ^2 \frac{\alpha }{2}}}

\csc \alpha = \frac{{1 + \tan ^2 \frac{\alpha }{2}}}{{2\tan \frac{\alpha }{2}}}

而被称为万能公式的原因是利用\tan \frac{\alpha }{2}的代换可以解决一些有关三角函数的积分。参见三角换元法。

\begin{align}
\tan\left(\frac{\eta}{2} \pm \frac{\theta}{2}\right) & = \frac{\sin\eta \pm \sin\theta}{\cos\eta + \cos\theta} = -\frac{\cos\eta - \cos\theta}{\sin\eta \mp \sin\theta}, \\[10pt]
\tan\left(\pm\frac{\theta}{2}\right) & = \frac{\pm\sin\theta}{1 + \cos\theta} = \frac{\pm\tan\theta}{\sec\theta + 1} = \frac{\pm 1}{\csc\theta + \cot\theta}, ~~~~(\eta = 0) \\[10pt]
\tan\left(\pm\frac{\theta}{2}\right) & = \frac{1-\cos\theta}{\pm\sin\theta} = \frac{\sec\theta-1}{\pm\tan\theta} = \pm(\csc\theta-\cot\theta), ~~~~(\eta=0) \\[10pt]
\tan\left(\frac{\pi}{4} \pm \frac{\theta}{2} \right) & = \frac{1 \pm \sin\theta}{\cos\theta} = \sec\theta \pm \tan\theta = \frac{\csc\theta \pm 1}{\cot\theta}, ~~~~(\eta=\frac{\pi}{2}) \\[10pt]
\tan\left(\frac{\pi}{4} \pm \frac{\theta}{2} \right) & = \frac{\cos\theta}{1 \mp \sin\theta} = \frac{1}{\sec\theta \mp \tan\theta} = \frac{\cot\theta}{\csc\theta \mp 1}, ~~~~(\eta=\frac{\pi}{2}) \\[10pt]
\frac{1 - \tan\frac{\theta}{2}}{1 + \tan\frac{\theta}{2}} & = \pm\sqrt{\frac{1 - \sin\theta}{1 + \sin\theta}}.
\end{align}

由二倍角公式，有：

\sin \alpha 
= 2\sin \frac{\alpha}{2}\cos \frac{\alpha}{2} =\frac{2\sin \frac{\alpha}{2}\cos \frac{\alpha}{2}}{\cos^2 \frac{\alpha}{2}+\sin^2\frac{\alpha}{2}} 
= \frac{2\sin \frac{\alpha}{2}\cos \frac{\alpha}{2} \div \cos^2 \frac{\alpha}{2}}{(\cos^2 \frac{\alpha}{2}+\sin^2\frac{\alpha}{2})\div \cos^2 \frac{\alpha}{2}}  
= \frac{2\frac{\sin \frac{\alpha}{2}}{\cos \frac{\alpha}{2}}}{1+\frac{\sin^2\frac{\alpha}{2}}{\cos^2 \frac{\alpha}{2}}}
=\frac{2\tan\frac{\alpha}{2}}{1+\tan^2\frac{\alpha}{2}}

\tan \alpha = \frac{{2\tan \frac{\alpha }{2}}}{{1 - \tan ^2 \frac{\alpha }{2}}}

再由同角三角函数间的关系，得出

\cos \alpha = \frac{\sin\alpha}{\tan\alpha}=\frac{\frac{{2\tan \frac{\alpha }{2}}}{{1 + \tan ^2 \frac{\alpha }{2}}}}{\frac{{2\tan \frac{\alpha }{2}}}{{1 - \tan ^2 \frac{\alpha }{2}}}} = \frac{{1 - \tan ^2 \frac{\alpha }{2}}}{{1 + \tan ^2 \frac{\alpha }{2}}}

与希罗在他的著作《Metrica》中的原始证明不同，在此我们用三角公式和公式变形来证明。设三角形的三边a, b ,c的对角分别为A, B ,C，则余弦定理为

\cos C = \frac{a^2+b^2-c^2}{2ab}

利用和平方、差平方、平方差等公式，从而有

\begin{align}
\sin C & = \sqrt{1-\cos^2 C} \\
& = \sqrt{(1+\cos C)(1-\cos C)} \\
& = \sqrt{\left( 1+\frac{a^2+b^2-c^2}{2ab} \right) \left( 1-\frac{a^2+b^2-c^2}{2ab} \right)} \\
& = \sqrt{\left( \frac{2ab+(a^2+b^2-c^2)}{2ab} \right) \left( \frac{2ab-(a^2+b^2-c^2)}{2ab} \right)} \\
& = \sqrt{\left( \frac{(2ab+a^2+b^2)-c^2}{2ab} \right) \left( \frac{c^2-(a^2+b^2-2ab)}{2ab} \right)} \\
& = \sqrt{\left[ \frac{(a+b)^2-c^2}{2ab} \right] \left[ \frac{c^2-(a-b)^2}{2ab} \right]} \\
& = \frac{\sqrt{(a+b+c)(a+b-c)(c+a-b)(c-a+b)}}{2ab} \\
& = \frac{\sqrt{(2s)(2s-2c)(2s-2b)(2s-2a)}}{2ab} \\
& = \frac{2}{ab} \sqrt{s(s-c)(s-b)(s-a)}
\end{align}

\begin{align}
A & = \frac{1}{2}ab \sin C \\
& = \frac{ab}{2} \cdot \frac{2}{ab} \sqrt{s(s-a)(s-b)(s-c)} \\
& = \sqrt{s(s-a)(s-b)(s-c)}
\end{align}

b^2=h^2+d^2

a^2=h^2+(c-d)^2

a^2-b^2=c^2-2cd

d=\frac{-a^2+b^2+c^2}{2c}

\begin{align}
h^2 & = b^2-\left(\frac{-a^2+b^2+c^2}{2c}\right)^2\\
& = \frac{(2bc-a^2+b^2+c^2)(2bc+a^2-b^2-c^2)}{4c^2}\\
& = \frac{((b+c)^2-a^2)(a^2-(b-c)^2)}{4c^2}\\
& = \frac{(b+c-a)(b+c+a)(a+b-c)(a-b+c)}{4c^2}\\
& = \frac{2(s-a)\cdot 2s\cdot 2(s-c)\cdot 2(s-b)}{4c^2}\\
& = \frac{4s(s-a)(s-b)(s-c)}{c^2}
\end{align}

\begin{align}
A & = \frac{ch}{2}\\
& = \sqrt{\frac{c^2}{4}\cdot \frac{4s(s-a)(s-b)(s-c)}{c^2}}\\
