圆排列并没有统一的精确定义。有些作者对圆排列的定义是仅有一个轮换的排列。其他作者则使用更宽松的定义，允许不动点的存在。

例如排列

\begin{pmatrix}
1 &2 &3 &4 &5 &6 &7 &8 \\
4 &2 &7 &6 &5 &8 &1 &3
\end{pmatrix} = \begin{pmatrix}
1 &4 &6 &8 &3 &7 &2 &5 \\
4 &6 &8 &3 &7 &1 &2 &5
\end{pmatrix}

有一个6-轮换和两个1-轮换（不动点）。对上述较为宽松的定义，这个排列是圆排列，而对较严格的定义则不算。

与一般的线性排列不同，圆排列由于首位元素相邻因此需要考虑由循环移位带来的相同排列，不考虑循环移位的排列数为P(n,r)，圆周上r个元素的循环移位数为r，故圆排列数为

Q(n,r) = \frac{P(n,r)}{r} = \frac{n!}{r\cdot(n-r)!}

特别地，n个元素的圆排列个数是(n-1)!，该结论也可以由波利亚计数定理得到。

注：输入参数total是给定图像中的像素数。输入参数histogram是灰度图像不同灰度级（典型的8位图像）的256元直方图。此函数输出图像的阈值。

function otsu(histogram, total) {
    var sum = 0;
    for (var i = 1; i < 256; ++i)
        sum += i * histogram[i];
    var sumB = 0;
    var wB = 0;
    var wF = 0;
    var mB;
    var mF;
    var max = 0.0;
    var between = 0.0;
    var threshold1 = 0.0;
    var threshold2 = 0.0;
    for (var i = 0; i < 256; ++i) {
        wB += histogram[i];
        if (wB == 0)
            continue;
        wF = total - wB;
        if (wF == 0)
            break;
        sumB += i * histogram[i];
        mB = sumB / wB;
        mF = (sum - sumB) / wF;
        between = wB * wF * (mB - mF) * (mB - mF);
        if ( between >= max ) {
            threshold1 = i;
            if ( between > max ) {
                threshold2 = i;
            }
            max = between;            
        }
    }
    return ( threshold1 + threshold2 ) / 2.0;
}

unsigned char otsu_threshold( int* histogram, int pixel_total )
{
    unsigned int sumB = 0;
    unsigned int sum1 = 0;
    float wB = 0.0f;
    float wF = 0.0f;
    float mF = 0.0f;
    float max_var = 0.0f;
    float inter_var = 0.0f;
    unsigned char threshold = 0;
    unsigned short index_histo = 0;

    for ( index_histo = 1; index_histo < 256; ++index_histo )
    {
        sum1 += index_histo * histogram[ index_histo ];
    }

    for (index_histo = 1; index_histo < 256; ++index_histo)
    {
        wB = wB + histogram[ index_histo ];
        wF = pixel_total - wB;
        if ( wB == 0 || wF == 0 )
        {
            continue;
        }
        sumB = sumB + index_histo * histogram[ index_histo ];
        mF = ( sum1 - sumB ) / wF;
        inter_var = wB * wF * ( ( sumB / wB ) - mF ) * ( ( sumB / wB ) - mF );
        if ( inter_var >= max_var )
        {
            threshold = index_histo;
            max_var = inter_var;
        }
    }

    return threshold;
}

