所有连续非负的凸形函数的积分都是S型函数，因此许多常见概率分布的累积分布函数会是S型函数。一个常见的例子是误差函数，它是正态分布的累积分布函数。

\ell = \frac{d}{\tan \alpha} + \frac{d}{\tan \beta}

根据三角恒等式\tan \alpha =\frac{\sin\alpha}{\cos\alpha}和\sin\left ( \alpha+\beta \right )=\sin\alpha\cos\beta+\cos\alpha\sin\beta，此式可等于：

\ell= d \left(\frac{\cos \alpha}{\sin \alpha} + \frac{\cos \beta}{\sin \beta}\right)

\ell = d\ \frac{ \sin(\alpha + \beta)}{\sin\alpha \sin\beta }

因此，

d = \ell\ \frac{ \sin\alpha \sin\beta }{ \sin(\alpha + \beta)}

由此便可简单定义出一未知点与观察点间的距离，以及与观察点往东西、南北向相差的位移量，终得完整座标。

与勒让德多项式一样，连带勒让德多项式在区间 [-1,1] 上也满足正交性。

\int_{-1}^{1} P_l^m(x) P_k^m(x)\mathrm dx = \frac{(l+m)!}{(l-m)!}\frac 2{2l+1}\delta_{kl}

这是因为，与勒让德方程一样，连带勒让德方程也是施图姆-刘维尔型的：

\left\{\frac{m^2}{1-x^2}-\frac{\mathrm d}{\mathrm dx}\left[(1-x^2)\frac{\mathrm d}{\mathrm dx}\right]\right\}P_l^m(x)=\lambda P_l^m(x),\quad \lambda=l(l+1),l\in\mathbb Z_0^+

正交性的另一种表述如下，它与下面提到的球谐函数有关。

\int_{0}^\pi P_l^m(\cos\theta) P_k^m(\cos\theta)\sin\theta\mathrm d\theta = \frac{(l+m)!}{(l-m)!}\frac 2{2l+1}\delta_{kl}

另见：球谐函数 球谐函数是球坐标下三维空间拉普拉斯方程的角度部分的解，构成一组完备的基组，有着重要的意义。

采用本文中定义的连带勒让德多项式的表达式，球谐函数可以表达为：

Y_l^m(\theta,\phi)=\sqrt{\frac{(l-m)!}{(l+m)!}\frac{2l+1}{4\pi}}P_l^m(\cos\theta)e^{im\phi}

由连带勒让德多项式的正交关系可以直接得到球谐函数的正交关系：

\int Y_l^m(\theta,\phi)Y_{k}^{n*}(\theta,\phi)\mathrm d\Omega=\delta_{kl}\delta_{mn}

式中 dΩ 是立体角元。

/* c2-2.h 线性表的单链表存储结构 */
typedef struct LNode
{
	ElemType data;
	struct LNode *next;
}LNode,*LinkList;

/* bo2-2.c 带有头结点的单链表(存储结构由c2-2.h定义)的基本操作(12个),包括算法2.8,2.9,2.10 */
void InitList(LinkList *L)
{	/* 操作结果：构造一个空的线性表L */
	*L=(LinkList)malloc(sizeof(struct LNode)); /* 产生头结点，并使L指向此头结点 */
	if(!*L) /* 存储分配失败 */
		exit(OVERFLOW);
	(*L)->next=NULL; /* 指针域为空 */
}

void DestroyList(LinkList *L)
{	/* 初始条件：线性表L已存在。操作结果：销毁线性表L */
	LinkList q;
	while(*L)
	{
		q=(*L)->next;
		free(*L);
		*L=q;
	}
}

void ClearList(LinkList L) /* 不改变L */
{	/* 初始条件：线性表L已存在。操作结果：将L重置为空表 */
	LinkList p,q;
	p=L->next; /* p指向第一个结点 */
	while(p) /* 没到表尾 */
	{
		q=p->next;
		free(p);
		p=q;
	}
	L->next=NULL; /* 头结点指针域为空 */
}

Status ListEmpty(LinkList L)
{	/* 初始条件：线性表L已存在。操作结果：若L为空表，则返回TRUE，否则返回FALSE */
	if(L->next) /* 非空 */
		return FALSE;
	else
		return TRUE;
}

int ListLength(LinkList L)
{	/* 初始条件：线性表L已存在。操作结果：返回L中数据元素个数 */
	int i=0;
	LinkList p=L->next; /* p指向第一个结点 */
	while(p) /* 没到表尾 */
	{
		i++;
		p=p->next;
	}
	return i;
}

Status GetElem(LinkList L,int i,ElemType *e) /* 算法2.8 */
{	/* L为带头结点的单链表的头指针。当第i个元素存在时，其值赋给e并返回OK，否则返回ERROR */
	int j=1; /* j为计数器 */
	LinkList p=L->next; /* p指向第一个结点 */
	while(p&&j<i) /* 顺指针向后查找，直到p指向第i个元素或p为空 */
	{
		p=p->next;
		j++;
	}
	if(!p||j>i) /* 第i个元素不存在 */
		return ERROR;
	*e=p->data; /* 取第i个元素 */
	return OK;
}

int LocateElem(LinkList L,ElemType e,Status(*compare)(ElemType,ElemType))
{	/* 初始条件: 线性表L已存在，compare()是数据元素判定函数(满足为1，否则为0) */
	/* 操作结果: 返回L中第1个与e满足关系compare()的数据元素的位序。 */
	/*           若这样的数据元素不存在，则返回值为0 */
	int i=0;
	LinkList p=L->next;
	while(p)
	{
		i++;
		if(compare(p->data,e)) /* 找到这样的数据元素 */
			return i;
		p=p->next;
	}
	return 0;
}

Status PriorElem(LinkList L,ElemType cur_e,ElemType *pre_e)
{	/* 初始条件: 线性表L已存在 */
	/* 操作结果: 若cur_e是L的数据元素，且不是第一个，则用pre_e返回它的前驱， */
	/*           返回OK；否则操作失败，pre_e无定义，返回INFEASIBLE */
	LinkList q,p=L->next; /* p指向第一个结点 */
	while(p->next) /* p所指结点有后继 */
	{
		q=p->next; /* q为p的后继 */
		if(q->data==cur_e)
		{
			*pre_e=p->data;
			return OK;
		}
		p=q; /* p向后移 */
	}
	return INFEASIBLE;
}

Status NextElem(LinkList L,ElemType cur_e,ElemType *next_e)
{	/* 初始条件：线性表L已存在 */
	/* 操作结果：若cur_e是L的数据元素，且不是最后一个，则用next_e返回它的后继， */
	/*           返回OK;否则操作失败，next_e无定义，返回INFEASIBLE */
	LinkList p=L->next; /* p指向第一个结点 */
	while(p->next) /* p所指结点有后继 */
	{
		if(p->data==cur_e)
		{
			*next_e=p->next->data;
			return OK;
		}
		p=p->next;
	}
	return INFEASIBLE;
}

Status ListInsert(LinkList L,int i,ElemType e) /* 算法2.9。不改变L */
{	/* 在带头结点的单链线性表L中第i个位置之前插入元素e */
	int j=0;
	LinkList p=L,s;
	while(p&&j<i-1) /* 寻找第i-1个结点 */
	{
		p=p->next;
		j++;
	}
	if(!p||j>i-1) /* i小于1或者大于表长 */
		return ERROR;
	s=(LinkList)malloc(sizeof(struct LNode)); /* 生成新结点 */
	s->data=e; /* 插入L中 */
	s->next=p->next;
	p->next=s;
	return OK;
}

Status ListDelete(LinkList L,int i,ElemType *e) /* 算法2.10。不改变L */
{	/* 在带头结点的单链线性表L中，删除第i个元素，并由e返回其值 */
	int j=0;
	LinkList p=L,q;
	while(p->next&&j<i-1) /* 寻找第i个结点，并令p指向其前岖 */
	{
		p=p->next;
		j++;
	}
	if(!p->next||j>i-1) /* 删除位置不合理 */
		return ERROR;
	q=p->next; /* 删除并释放结点 */
	p->next=q->next;
	*e=q->data;
	free(q);
	return OK;
}

void ListTraverse(LinkList L,void(*vi)(ElemType))
/* vi的形参类型为ElemType，与bo2-1.c中相应函数的形参类型ElemType&不同 */
{	/* 初始条件：线性表L已存在。操作结果：依次对L的每个数据元素调用函数vi() */
	LinkList p=L->next;
	while(p)
	{
		vi(p->data);
		p=p->next;
	}
	printf("\n");
}

// 线性表的静态单链表存储结构
#define MAX_SIZE 100 // 链表的最大长度
typedef struct {
    ElemType data; //此處的ElemType可以自由代換（如int/float等）
    int cur;
} component, SLinkList[MAX_SIZE];

// 一个数组只生成一个静态链表的基本操作(11个)
#define DestroyList ClearList // DestroyList()和ClearList()的操作是一样的

void InitList(SLinkList L) {
    // 构造一个空的链表L，表头为L的最后一个单元L[MAX_SIZE-1]，其余单元链成
    // 一个备用链表，表头为L的第一个单元L[0]，“0”表示空指针
    int i;
    L[MAX_SIZE - 1].cur = 0; // L的最后一个单元为空链表的表头
    for (i = 0; i < MAX_SIZE - 2; i++) // 将其余单元链接成以L[0]为表头的备用链表
        L[i].cur = i + 1;
    L[MAX_SIZE - 2].cur = 0;
}

void ClearList(SLinkList L) {
    // 初始条件：线性表L已存在。操作结果：将L重置为空表
    int i, j, k;
    i = L[MAX_SIZE - 1].cur; // 链表第一个结点的位置
    L[MAX_SIZE - 1].cur = 0; // 链表空
    k = L[0].cur; // 备用链表第一个结点的位置
    L[0].cur = i; // 把链表的结点连到备用链表的表头
    while (i) { // 没到链表尾
        j = i;
        i = L[i].cur; // 指向下一个元素
    }
    L[j].cur = k; // 备用链表的第一个结点接到链表的尾部
}

Status ListEmpty(SLinkList L) {
    // 若L是空表，返回TRUE；否则返回FALSE
    if (L[MAX_SIZE - 1].cur == 0) // 若为空表
        return TRUE;
    else
        return FALSE;
}

int ListLength(SLinkList L) {
    // 返回L中数据元素个数
    int j = 0, i = L[MAX_SIZE - 1].cur; // i指向第一个元素
    while (i) { // 没到静态链表尾
        i = L[i].cur; // 指向下一个元素
        j++;
    }
    return j;
}

Status GetElem(SLinkList L, int i, ElemType *e) {
    // 用e返回L中第i个元素的值
    int l, k = MAX_SIZE - 1; // k指向表头序号
    if (i < 1 || i > ListLength(L))
        return ERROR;
    for (l = 1; l <= i; l++) // 移动到第i个元素处
        k = L[k].cur;
    *e = L[k].data;
    return OK;
}

int LocateElem(SLinkList L, ElemType e) { // 算法2.13(有改动)
    // 在静态单链线性表L中查找第1个值为e的元素。若找到，则返回它在L中的
    // 位序，否则返回0。(与其它LocateElem()的定义不同)
    int i = L[MAX_SIZE - 1].cur; // i指示表中第一个结点
    while (i && L[i].data != e) // 在表中顺链查找(e不能是字符串)
        i = L[i].cur;
    return i;
}

Status PriorElem(SLinkList L, ElemType cur_e, ElemType *pre_e) {
    // 初始条件：线性表L已存在
    // 操作结果：若cur_e是L的数据元素，且不是第一个，则用pre_e返回它的前驱，
    // 否则操作失败，pre_e无定义
    int j, i = L[MAX_SIZE - 1].cur; // i指示链表第一个结点的位置
    do { // 向后移动结点
        j = i;
        i = L[i].cur;
    } while (i && cur_e != L[i].data);
    if (i) { // 找到该元素
        *pre_e = L[j].data;
        return OK;
    }
    return ERROR;
}

Status NextElem(SLinkList L, ElemType cur_e, ElemType *next_e) {
    // 初始条件：线性表L已存在
    // 操作结果：若cur_e是L的数据元素，且不是最后一个，则用next_e返回它的后继
    // 否则操作失败，next_e无定义
    int j, i = LocateElem(L, cur_e); // 在L中查找第一个值为cur_e的元素的位置
    if (i) { // L中存在元素cur_e
        j = L[i].cur; // cur_e的后继的位置
        if (j) { // cur_e有后继
            *next_e = L[j].data;
            return OK; // cur_e元素有后继
        }
    }
    return ERROR; // L不存在cur_e元素，cur_e元素无后继
}

Status ListInsert(SLinkList L, int i, ElemType e) {
    // 在L中第i个元素之前插入新的数据元素e
    int l, j, k = MAX_SIZE - 1; // k指向表头
    if (i < 1 || i > ListLength(L) + 1)
        return ERROR;
    j = Malloc(L); // 申请新单元
    if (j) { // 申请成功
        L[j].data = e; // 赋值给新单元
        for (l = 1; l < i; l++) // 移动i-1个元素
            k = L[k].cur;
        L[j].cur = L[k].cur;
        L[k].cur = j;
        return OK;
    }
    return ERROR;
}

Status ListDelete(SLinkList L, int i, ElemType *e) {
    // 删除在L中第i个数据元素e，并返回其值
    int j, k = MAX_SIZE - 1; // k指向表头
    if (i < 1 || i > ListLength(L))
        return ERROR;
    for (j = 1; j < i; j++) // 移动i-1个元素
        k = L[k].cur;
    j = L[k].cur;
    L[k].cur = L[j].cur;
    *e = L[j].data;
    Free(L, j);
    return OK;
}

void ListTraverse(SLinkList L, void(*vi)(ElemType)) {
    // 初始条件：线性表L已存在。操作结果：依次对L的每个数据元素调用函数vi()
    int i = L[MAX_SIZE - 1].cur; // 指向第一个元素
    while (i) { // 没到静态链表尾
        vi(L[i].data); // 调用vi()
        i = L[i].cur; // 指向下一个元素
    }
    printf("\n");
}

另一个例子是集合范畴上的分布单子（distribution monad）\mathcal{D}，其将集合X映至其上所有有限支撑的概率分布的集合。该等分布，是函数f : X \to [0,1]，仅于有限多个元素x \in X处取值非零，而各元素处取值之和为1。以符号表示，

\mathcal{D}(X) = \left\{
f: X \to [0,1] : \begin{matrix}
\#\text{supp}(f) < +\infty, \\
\sum_{x \in X} f(x) = 1
\end{matrix}
\right\}.

可由定义证明，分布单子上的代数，等同于凸集，即集合要配备二元运算+_r（对每个r \in [0,1]），满足的公理比照欧氏空间中，凸组合(x, y) \mapsto rx + (1-r)y具备的性质。

可变长度码的优点在于，不太可能出现的源符号会分配到较长的码字，而常出现的源符号会分配到较短的码字，从而给出较低的预期码字长度。对于上面的例子，如果 (a, b, c, d) 出现的概率为\textstyle\left(\frac{1}{2}, \frac{1}{4}, \frac{1}{8}, \frac{1}{8}\right) ，使用上述编码表示源符号的预期位数为：

1\times\frac{1}{2}+2\times\frac{1}{4}+3\times\frac{1}{8}+3\times\frac{1}{8}=\frac{7}{4}

由于该源的熵为每个符号 1.7500 位，因此该编码能尽可能地压缩源，以便可以以零错误恢复源。

上列公式并不容易理解其来由, 若移项重新整理, 并刻意以 A_s 提醒此方位角为南方位角, 则可得:

\begin{align}
X_h &= \cos a \cdot \cos A_S &&= \sin \phi \cdot \cos \delta \cdot \cos H -\cos \phi \cdot \sin \delta \\

Y_h &= \cos a \cdot \sin A_S &&= \cos \delta \cdot \sin H \\

Z_h &= \sin a                &&= \cos \phi \cdot \cos \delta \cdot \cos H + \sin \phi \cdot \sin \delta \\
\end{align}

其矩阵形式则为:

\begin{bmatrix}
X_h \\
Y_h \\
Z_h
\end{bmatrix}
=
\begin{bmatrix}
\cos a \cdot \cos A_S \\
\cos a \cdot \sin A_S \\
\sin a \\
\end{bmatrix}
=
\begin{bmatrix}
\sin \phi & 0 & - \cos \phi \\
0         & 1 & 0      \\
\cos \phi & 0 &   \sin \phi
\end{bmatrix}
\times
\begin{bmatrix}
\cos \delta \cdot \cos H \\
\cos \delta \cdot \sin H \\
\sin \delta
\end{bmatrix}

A_S = atan2(Y_h, X_h), a = \arcsin(Z_h)

其中, 最右边要被转换的行向量表示赤道极座标 (\alpha, \delta) 或 (H, \delta) (H = LST - \alpha) 投影在赤道面某选定直角座标的三个分量 (X_e, Y_e, Z_e), 等号左边的转换后所得行向量表示地平极座标 (A_S, a) 投影在地平面某选定直角座标的三个分量 (X_h, Y_h, Z_h). 中间的转换矩阵代表将赤道座标沿著子午线由天球北极 (Z 轴) 转向赤道面 (X轴) 转动 90-\phi 度角的座标旋转矩阵. 这样的矩阵式说明了原公式的直觉意义, 对于需要时常计算的观星者,航海家或天文计算程式员而言比较不必硬记, 也较不容易弄错.

上列矩阵转换公式, 也让地平座标转赤道座标变得容易. 事实上, 只要把转换对象调换, 并进行逆转换即可. 换句话说, 前式的两个行向量只要互相调换, 并把原来的转换矩阵变成他的逆矩阵 (inverse matrix) 即可得到反向转换公式. 有趣的是, 座标转换的逆矩阵也是他的转置矩阵 (transpose matrix), 也就是行列互换的矩阵, 因此并不需要费力去求原转换矩阵的逆矩阵. 因此, 我们可以轻易得到:

\begin{bmatrix}
X_e \\
Y_e \\
Z_e
\end{bmatrix}
=
\begin{bmatrix}
\cos \delta \cdot \cos H \\
\cos \delta \cdot \sin H \\
\sin \delta
\end{bmatrix}
=
\begin{bmatrix}
\sin \phi & 0 & \cos \phi \\
0         & 1 & 0      \\
- \cos \phi & 0 &   \sin \phi
\end{bmatrix}
\times
\begin{bmatrix}
\cos a \cdot \cos A_S \\
\cos a \cdot \sin A_S \\
\sin a \\
\end{bmatrix}

亦即

\begin{align}
X_e &= \cos \delta \cdot \cos H &&= \sin \phi \cdot \cos a \cdot \cos A_S + \cos \phi \cdot \sin a \\

Y_e &= \cos \delta \cdot \sin H &&= \cos a \cdot \sin A_S \\

Z_e &= \sin \delta              &&= - \cos \phi \cdot \cos a \cdot \cos A_S + \sin \phi \cdot \sin a \\
\end{align}

H = atan2(Y_e, X_e), \alpha = LST(t,\lambda) - H(\alpha), \delta = \arcsin(Z_e).

其中, LST(t, \lambda) 为观测者所在经度 \lambda 于观测时间 t 的本地恒星时.

赤道转地平, 求 A_N 的方法除了用先前方法算出 A_S 再加 180 度之外, 也可以将原来的转换公式中的 X_h 跟 Y_h等号右侧方程式都加负号, 并把等号左侧的 A_S 改成 A_N 即可. 其结果是:

\begin{align}
X_{hN} &= \cos a \cdot \cos A_N  &&= - \sin \phi \cdot \cos \delta \cdot \cos H +\cos \phi \cdot \sin \delta &&= - X_h\\

Y_{hN} &= \cos a \cdot \sin A_N  &&= - \cos \delta \cdot \sin H                                              &&= - Y_h\\

Z_{hN} &= \sin a                 &&= \cos \phi \cdot \cos \delta \cdot \cos H + \sin \phi \cdot \sin \delta  &&= + Z_h\\
\end{align}

A_N = atan2(Y_{hN}, X_{hN}), a = \arcsin(Z_{hN}), 或者 A_N = atan2(-Y_{h}, -X_{h}), a = \arcsin(Z_{h}). 同时:

\begin{align}
\tan A_N &= \frac{Y_{hN}}{X_{hN}} = \frac{-Y_{h}}{-X_{h}} = \frac{Y_{h}}{X_{h}} = \tan A_S = \tan A \\
\end{align}

两者相除后，除正负号的区别外，形式完全一样，已无法区分这里的方位角是南方位角或北方位角。且已失去判断象限的讯息，必须由分子分母的正负来辅助判断。这跟之前讨论如何由 \tan A (即 \tan A_S) 求 A 的情况一样。

有兴趣者可以把他转成矩阵转换式, 会发现这样的转换是经过两道转换手续, 即先转成原先的南地平, 再把 X 轴转 180 度, 也就是 X 值跟 Y 值都取负号.

\begin{bmatrix}
X_{hN} \\
Y_{hN} \\
Z_{hN}
\end{bmatrix}
=
\begin{bmatrix}
\cos a \cdot \cos A_N \\
\cos a \cdot \sin A_N \\
\sin a \\
\end{bmatrix}
=
\begin{bmatrix}
-1 & 0 & 0  \\
0  & -1 & 0 \\
0  & 0 &  1
\end{bmatrix}
\times
\begin{bmatrix}
\sin \phi & 0 & - \cos \phi \\
0         & 1 & 0      \\
\cos \phi & 0 &   \sin \phi
\end{bmatrix}
\times
\begin{bmatrix}
\cos \delta \cdot \cos H \\
\cos \delta \cdot \sin H \\
\sin \delta
\end{bmatrix}

天体出现在地平线上的时间\Delta T_{RS}，即从上升到下沉所经历的时间，其实就是相当于两倍 H_0 的时间。如果天体是指太阳的话，这就是白天的时间或日照时间。对其他天体而言，就是最长可观测的时间 (不考虑曙暮光的影响的话)。

\begin{align}
\Delta T_{RS}   &= 2 H_0 / R_0 \times {24^h}   && \text{= twice the time for } H_0 \\
                &= 24^h   && \text{if} \cos H_0 < -1 (\approx \tan \phi \cdot tan \delta > +1) \text{(never set)}  \\
                &= 0^h    && \text{if} \cos H_0 > +1 (\approx \tan \phi \cdot tan \delta < -1) \text{(never rise)} \\  
\end{align}

天体出没的方位角，显然只跟天体所在的赤纬平行圈及观测地纬度有关，与出没时间无关。所有赤纬相同的天体都在同一天球赤纬平行圈上，该平行圈与地平线交于相同的两点，其方位即天体出或没时的方位。给定出没时的天体高度角a_0 及观测地纬度 \phi，假设A_{S0} 及 A_{N0} 分别为对应的南方位角及北方位角，则该方位角可计算如下 (如果有出没状况的话)：

\begin{align}
\sin \delta              &= - \cos \phi \cdot \cos a_0 \cdot \cos A_{S0} + \sin \phi \cdot \sin a_0 &&(\triangleq Z_e^0) \\
\Rightarrow \cos A_{S0}  &= \frac{\sin \delta - \sin \phi \cdot \sin a_0}{- \cos \phi \cdot \cos a_0}
                        && \text{(if } a_0 \ne 0 \text{)} \\
                         &= \frac{\sin \delta}{- \cos \phi}
                        && \text{(if } a_0 = 0 \text{)} \\
\text{Let } A_{S0} &=
\arccos (\frac{\sin \delta - \sin \phi \cdot \sin a_0}{- \cos \phi \cdot \cos a_0}) &&\text{if } cos H_0 \in [-1,+1], \text{has rise/set} \\
\Rightarrow A_{S0R} &= -A_{S0} \equiv 360^\circ -A_{S0}  && H_0 \in [-0,-180] \text{ (South Azimuth for Rise)}\\
            A_{S0S} &= +A_{S0}                           && H_0 \in [+0,+180] \text{ (South Azimuth for Set)}\\
\text{and, } A_{N0} &= A_{S0} + 180^\circ                             && \text{(North Azimuth)}\\
\end{align}

另外, 也可以直接由 A_N 的公式, 求解日出日落时的北方位角,

\begin{align}
\sin \delta              &= \cos \phi \cdot \cos a_0 \cdot \cos A_{N0} + \sin \phi \cdot \sin a_0 &&(\triangleq Z_{eN}^0)\\
\Rightarrow \cos A_{N0}  &= \frac{\sin \delta - \sin \phi \cdot \sin a_0}{\cos \phi \cdot \cos a_0}
                        && \text{(if } a_0 \ne 0 \text{)} \\
                         &= \frac{\sin \delta}{\cos \phi}
                        && \text{(if } a_0 = 0 \text{)} \\
\text{Let } A_{N0} &=
\arccos (\frac{\sin \delta - \sin \phi \cdot \sin a_0}{\cos \phi \cdot \cos a_0}) &&\text{if } cos H_0 \in [-1,+1], \text{has rise/set} \\
\Rightarrow A_{N0R} &= +A_{N0}                           && H_0 \in [-0,-180] \text{ (North Azimuth for Rise)}\\
            A_{N0S} &= -A_{N0} \equiv 360^\circ -A_{N0}  && H_0 \in [+0,+180] \text{ (North Azimuth for Set)}\\            
\text{and, } A_{S0} &= A_{N0} - 180^\circ                              && \text{(South Azimuth)}\\
\end{align}

在经过经验模态分解（EMD）将讯号分解为若干个本质模态函数（IMF）后，下一步便是对每一个 IMF 分量进行希尔伯特转换（Hilbert Transform），以求得其瞬时频率与瞬时振幅。这部分是 HHT 与传统傅立叶分析最大的区别所在。

对于每一个 IMF 分量 c_j(t)，我们定义其希尔伯特转换为： :H[c_j(t)] = \frac{1}{\pi} \text{P.V.} \int_{-\infty}^{\infty} \frac{c_j(\tau)}{t-\tau} d\tau 其中 P.V. 代表柯西主值（Cauchy Principal Value）。

利用希尔伯特转换，我们可以建构出解析讯号（Analytic Signal）z_j(t)： :z_j(t) = c_j(t) + i H[c_j(t)] = a_j(t) e^{i\theta_j(t)}

其中，a_j(t) 为该分量的瞬时振幅（Instantaneous Amplitude），\theta_j(t) 为瞬时相位（Instantaneous Phase）： :a_j(t) = \sqrt{c_j^2(t) + H^2[c_j(t)]} :\theta_j(t) = \arctan \left( \frac{H[c_j(t)]}{c_j(t)} \right)

有了瞬时相位，我们可以定义具有物理意义的瞬时频率（Instantaneous Frequency）： :\omega_j(t) = \frac{d\theta_j(t)}{dt}

这与傅立叶分析中定义的「频率」有本质上的不同。傅立叶分析的频率是定义在一段完整的时间区间内（全域性质），代表的是弦波的重复性；而 HHT 定义的瞬时频率是相位的微分（局部性质），允许频率随著时间连续变化，这对于描述非线性系统（如频率随振幅变化的系统）至关重要。

将所有 IMF 分量的瞬时振幅与瞬时频率结合，我们可以得到讯号在时频平面上的能量分布，称为希尔伯特谱（Hilbert Spectrum），记为 H(\omega, t)： :H(\omega, t) = \text{Re} \sum_{j=1}^{n} a_j(t) e^{i \int \omega_j(t) dt}

此外，若将希尔伯特谱对时间积分，则可得到边际谱（Marginal Spectrum），其物理意义类似于傅立叶频谱，但更真实地反映了讯号在该频率下的总能量累积： :h(\omega) = \int_{0}^{T} H(\omega, t) dt

