在数学中，有不只一个积分称作狄利克雷积分，都由德国数学家约翰·彼得·古斯塔夫·勒热纳·狄利克雷提出。 其中一个内容如下：

\int_0^\infty \frac{\sin x}{x}\,dx = \frac{\pi}{2}

这个积分不是绝对收敛的，因此勒贝格积分甚至不能定义这个积分，但它在黎曼积分或Henstock–Kurzweil积分是有定义的。  可以通过多种方式导出这个（黎曼或Henstock）积分的值。例如，该值可以通过计算双反常积分确定，也可以通过在积分符号内取微分来确定。

\begin{align}
\int_0^\infty \frac{\sin x}{x}\,dx &= \lim _{a \to \infty} \int_0^a \frac{\sin x}{x}\,dx =\lim _{a \to \infty} \int_0^a \frac{1}{x}\,d(1 - \cos x) = \lim _{a \to \infty} \frac{1 - \cos x}{x}| _0^a - \int_0^a (1 - \cos x)\,d\frac{1}{x} \\
&= \lim _{a \to \infty} \frac{2 \sin^2 \frac{x}{2}}{x} | _0^a  + \int_0^a  \frac{2 \sin^2 \frac{x}{2}}{x^2}\,dx = \lim _{a \to \infty} \int_0^1  \frac{2 \sin^2 \frac{x}{2}}{x^2}\,dx + \int_1^a  \frac{2 \sin^2 \frac{x}{2}}{x^2}\,dx \\
&< \int_0^1  \frac{2 \sin^2 \frac{x}{2}}{x^2}\,dx + \lim _{a \to \infty} \int_1^a \frac{2}{x^2}\,dx = \int_0^1  \frac{2 \sin^2 \frac{x}{2}}{x^2}\,dx + 2
\end{align}

因为\lim _{a \to \infty} \int_0^1  \frac{2 \sin^2 \frac{x}{2}}{x^2}\,dx + \int_1^a  \frac{2 \sin^2 \frac{x}{2}}{x^2}\,dx 递增并且有上界\int_0^1  \frac{2 \sin^2 \frac{x}{2}}{x^2}\,dx + 2，故由单调收敛定理知，\int_0^\infty \frac{\sin x}{x}\,dx有极限值I。

DFT（离散傅里叶变换）是对离散周期信号的一种傅里叶变换，对于有限长信号，则相当于对其周期延拓进行变换。在频域上，DFT的离散谱是对DTFT连续谱的等间隔采样。

F_{DFT}(\omega_k) 
= \left. F_{DTFT}(e^{i \omega T}) \, \right|_{\omega = 2 \pi \frac{k}{N}}
= \left. \sum_{n=0}^{N-1} f(nT) \,e^{-i \omega nT} \, \right|_{\omega = 2 \pi \frac{k}{N}} 
= \sum_{n=0}^{N-1} f(nT) \,e^{-i 2 \pi \frac{k n T}{N}}

推荐并且适用于大多数用户的生成器，是具有64位状态和32位输出的 PCG-XSH-RR 生成器。它可以通过以下方式实现：

#include <stdint.h>
static uint64_t       state      = 0x4d595df4d0f33173;		// 生成器的状态，初始值可以根据种子进行改变
static uint64_t const multiplier = 6364136223846793005u;    // 状态转换函数——线性同余方法（LCG）的乘数
static uint64_t const increment  = 1442695040888963407u;	// 线性同余方法（LCG）的增量，可以是任意奇数

// 循环移位函数
static uint32_t rotr32(uint32_t x, unsigned r)
{
	return x >> r | x << (-r & 31);
}

// 使用PCG生成器生成伪随机数
uint32_t pcg32(void)
{
	uint64_t x = state;
	unsigned count = (unsigned)(x >> 59);		// 59 = 64 - 5

	state = x * multiplier + increment;
	x ^= x >> 18;								// 18 = (64 - 27)/2
	return rotr32((uint32_t)(x >> 27), count);	// 27 = 32 - 5
}

// 使用提供的种子值初始化生成器
void pcg32_init(uint64_t seed)
{
	state = seed + increment;
	(void)pcg32();
}

范例中的生成器为了促进处理器的指令级并行，以提高该生成器在现代超标量处理器上的性能，选择了将初始状态作为输出函数的输入，而非其最终状态（即状态转换函数执行后的状态）。

此外，还有一个稍微更快的版本，剔除了LCG算法中的增量，使其状态转换函数成为莱默生成器的一种变体，并且使用了性能更弱的XSH-RS输出函数。其循环周期仅为上述范例的四分之一：

static uint64_t mcg_state = 0xcafef00dd15ea5e5u;	// 必须是奇数

uint32_t pcg32_fast(void)
{
	uint64_t x = mcg_state;
	unsigned count = (unsigned)(x >> 61);	// 61 = 64 - 3

	mcg_state = x * multiplier;
	x ^= x >> 22;
	return (uint32_t)(x >> (22 + count));	// 22 = 32 - 3 - 7
}

void pcg32_fast_init(uint64_t seed)
{
	mcg_state = 2*seed + 1;
	(void)pcg32_fast();
}

尽管如此，由于这个算法依旧保留了性能开销最大的64位×64位乘法，其增加的性能并不多，因此第二个范例内的生成器只应在极端场景下使用。

在 32 位处理器上执行时，以上所有代码范例都必然会使用三个 32×32→64 位的乘法运算来实现 64×64 位乘法。 为了将这个运算减少到两个，可以使用一些性能几乎与 64 位乘数一样好的 32 位乘数，例如 0xf13283ad、0xffffffff0e703b65 或 0xf2fc5985。

C_c(X) 意为由所有支集为紧的连续函数 f:X\to\C 所构成的函数空间。

定理： X 是局部紧的豪斯多夫空间 ，则对正线性泛函 \Lambda:C_c(X)\to\R^+，存在一个含有所有 X 的博雷尔集的Σ-代数 \mathfrak{M} ，且存在唯一的测度\mu:\mathfrak{M}\to\R^{+}\cup\{-\infty,\,\infty\} 使得

\Lambda(f) = \int_X f \, d \mu

且（以下的条件称为正则的）

对所有 X 的紧子集 K\subseteq X ，\mu(K)\in \R。

若 E\in \mathfrak{M}  ，则 \mu(E) = \inf \{\mu(U): E \subseteq U,\,U \text{ is open}\}

若 E\in \mathfrak{M} 且 \mu(E)\in \R ，则 \mu(E) = \sup \{\mu(K): K \subseteq E,\,K \text{ is compact}\}

若O 为 X 的开集，则\mu(O) = \sup \{\mu(K): K \subseteq O,\,K \text{ is compact}\}

第二种长球面坐标 (\sigma,\ \tau,\ \phi) 的标度因子分别为:

h_{\sigma} = a\sqrt{\frac{\sigma^{2} - \tau^{2}}{\sigma^{2} - 1}} 、

h_{\tau} = a\sqrt{\frac{\sigma^{2} - \tau^{2}}{1 - \tau^{2}}} 、

h_{\phi} = a \sqrt{\left( \sigma^{2} - 1 \right) \left( 1 - \tau^{2} \right)} 。

无穷小体积元素是

dV = a^{3} \left( \sigma^{2} - \tau^{2} \right) d\sigma d\tau d\phi 。

拉普拉斯算子是

\nabla^{2} \Phi = 
\frac{1}{a^{2} \left( \sigma^{2} - \tau^{2} \right)}
\left\{
\frac{\partial}{\partial \sigma} \left[ 
\left( \sigma^{2} - 1 \right) \frac{\partial \Phi}{\partial \sigma}
\right] + 
\frac{\partial}{\partial \tau} \left[ 
\left( 1 - \tau^{2} \right) \frac{\partial \Phi}{\partial \tau}
\right]
\right\}
+ \frac{1}{a^{2} \left( \sigma^{2} - 1 \right) \left( 1 - \tau^{2} \right)}
\frac{\partial^{2} \Phi}{\partial \phi^{2}} 。

其它微分算子，像 \nabla \cdot \mathbf{F} ， \nabla \times \mathbf{F} ，都可以用 (\mu,\ \nu,\ \phi) 坐标表示，只要将标度因子代入在正交坐标系条目内对应的一般公式。

/* c2-1.h 线性表的动态分配顺序存储结构 */
#define LIST_INIT_SIZE 10 /* 线性表存储空间的初始分配量 */
#define LIST_INCREMENT 2 /* 线性表存储空间的分配增量 */
typedef struct
{
	ElemType *elem; /* 存储空间基址 */
	int length; /* 当前长度 */
	int listsize; /* 当前分配的存储容量(以sizeof(ElemType)为单位) */
}SqList;

/* bo2-1.c 顺序表示的线性表(存储结构由c2-1.h定义)的基本操作(12个),包括算法2.3,2.4,2.5,2.6 */
void InitList(SqList *L) /* 算法2.3 */
{	/* 操作结果：构造一个空的顺序线性表L */
	(*L).elem=(ElemType*)malloc(LIST_INIT_SIZE*sizeof(ElemType));
	if(!(*L).elem)
		exit(OVERFLOW); /* 存储分配失败 */
	(*L).length=0; /* 空表长度为0 */
	(*L).listsize=LIST_INIT_SIZE; /* 初始存储容量 */
}

void DestroyList(SqList *L)
{	/* 初始条件：顺序线性表L已存在。操作结果：销毁顺序线性表L */
	free((*L).elem);
	(*L).elem=NULL;
	(*L).length=0;
	(*L).listsize=0;
}

void ClearList(SqList *L)
{	/* 初始条件：顺序线性表L已存在。操作结果：将L重置为空表 */
	(*L).length=0;
}

Status ListEmpty(SqList L)
{	/* 初始条件：顺序线性表L已存在。操作结果：若L为空表，则返回TRUE，否则返回FALSE */
	if(L.length==0)
		return TRUE;
	else
		return FALSE;
}

int ListLength(SqList L)
{	/* 初始条件：顺序线性表L已存在。操作结果：返回L中数据元素个数 */
	return L.length;
}

Status GetElem(SqList L,int i,ElemType *e)
{	/* 初始条件：顺序线性表L已存在,1≤i≤ListLength(L)。操作结果：用e返回L中第i个数据元素的值 */
	if(i<1||i>L.length)
		return ERROR;
	*e=*(L.elem+i-1);
		return OK;
}

int LocateElem(SqList L,ElemType e,Status(*compare)(ElemType,ElemType))
{	/* 初始条件：顺序线性表L已存在，compare()是数据元素判定函数(满足为1，否则为0) */
	/* 操作结果：返回L中第1个与e满足关系compare()的数据元素的位序。 */
	/*           若这样的数据元素不存在，则返回值为0。算法2.6 */
	ElemType *p;
	int i=1; /* i的初值为第1个元素的位序 */
	p=L.elem; /* p的初值为第1个元素的存储位置 */
	while(i<=L.length&&!compare(*p++,e))
		++i;
	if(i<=L.length)
		return i;
	else
		return 0;
}

Status PriorElem(SqList L,ElemType cur_e,ElemType *pre_e)
{	/* 初始条件：顺序线性表L已存在 */
	/* 操作结果：若cur_e是L的数据元素，且不是第一个，则用pre_e返回它的前驱， */
	/*           否则操作失败，pre_e无定义 */
	int i=2;
	ElemType *p=L.elem+1;
	while(i<=L.length&&*p!=cur_e)
	{
		p++;
		i++;
	}
	if(i>L.length)
		return INFEASIBLE; /* 操作失败 */
	else
	{
		*pre_e=*--p;
		return OK;
	}
}

Status NextElem(SqList L,ElemType cur_e,ElemType *next_e)
{	/* 初始条件：顺序线性表L已存在 */
	/* 操作结果：若cur_e是L的数据元素，且不是最后一个，则用next_e返回它的后继， */
	/*           否则操作失败，next_e无定义 */
	int i=1;
	ElemType *p=L.elem;
	while(i<L.length&&*p!=cur_e)
	{
		i++;
		p++;
	}
	if(i==L.length)
		return INFEASIBLE; /* 操作失败 */
	else
	{
		*next_e=*++p;
		return OK;
	}
}

Status ListInsert(SqList *L,int i,ElemType e) /* 算法2.4 */
{	/* 初始条件：顺序线性表L已存在，1≤i≤ListLength(L)+1 */
	/* 操作结果：在L中第i个位置之前插入新的数据元素e，L的长度加1 */
	ElemType *newbase,*q,*p;
	if(i<1||i>(*L).length+1) /* i值不合法 */
		return ERROR;
	if((*L).length>=(*L).listsize) /* 当前存储空间已满,增加分配 */
	{
		newbase=(ElemType *)realloc((*L).elem,((*L).listsize+LIST_INCREMENT)*sizeof(ElemType));
		if(!newbase)
			exit(OVERFLOW); /* 存储分配失败 */
		(*L).elem=newbase; /* 新基址 */
		(*L).listsize+=LIST_INCREMENT; /* 增加存储容量 */
	}
	q=(*L).elem+i-1; /* q为插入位置 */
	for(p=(*L).elem+(*L).length-1;p>=q;--p) /* 插入位置及之后的元素右移 */
		*(p+1)=*p;
	*q=e; /* 插入e */
	++(*L).length; /* 表长增1 */
	return OK;
}

Status ListDelete(SqList *L,int i,ElemType *e) /* 算法2.5 */
{	/* 初始条件：顺序线性表L已存在，1≤i≤ListLength(L) */
	/* 操作结果：删除L的第i个数据元素，并用e返回其值，L的长度减1 */
	ElemType *p,*q;
	if(i<1||i>(*L).length) /* i值不合法 */
		return ERROR;
	p=(*L).elem+i-1; /* p为被删除元素的位置 */
	*e=*p; /* 被删除元素的值赋给e */
	q=(*L).elem+(*L).length-1; /* 表尾元素的位置 */
	for(++p;p<=q;++p) /* 被删除元素之后的元素左移 */
		*(p-1)=*p;
	(*L).length--; /* 表长减1 */
	return OK;
}

void ListTraverse(SqList L,void(*vi)(ElemType*))
{	/* 初始条件：顺序线性表L已存在 */
	/* 操作结果：依次对L的每个数据元素调用函数vi() */
	/*           vi()的形参加'&'，表明可通过调用vi()改变元素的值 */
	ElemType *p;
	int i;
	p=L.elem;
	for(i=1;i<=L.length;i++)
		vi(p++);
	printf("\n");
}

