平移在图讯号时域中亦因为没有好的顺序关系，无法被良好的直接定义。

但因一般数位讯号处理的平移运算等价于将讯号与一个单位脉冲讯号折积，其推广定义可以利用此性质

s_{out}=s_{in}*\delta_n=VD_{\hat{s}_{in}}V^{-1}\delta_n=VD_{\hat{s}_{in}}u_n，其中\delta_n(k) = \begin{cases} 1, & \text{if }n=k \\ 0, & \text{if }n\neq k \end{cases}

滤波是让输入讯号经过一系统，产生输出讯号的过程。在时域中的表现形式为

s_{out}=Hs_{in}

若H是线性非移变系统，存在多项式传递函数h使得h=h(S)，故

Hs_{in}=h(S)s_{in}=h(V\Lambda V^{-1})s_{in}=Vh(\Lambda)V^{-1}s_{in}=VD_{\hat{s}_H}V^{-1}s_{in}

与折积的定义比较，可知其实可将「对s_{in}使用H滤波」看作「将s_{in}与另一个信号s_H作折积」，其中s_H符合\hat{s}_H=(h(\lambda_1),h(\lambda_2),...h(\lambda_{N-1}))^T，

此时称s_H为H的脉冲响应，\hat{s}_H为H的频率响应。

较常用的上同调是 H^1 与 H^2。从标准分解可导出以下的描述：

H^1(G, M) = \dfrac{\{ f: G \to M | \forall g, g', \;  f(gg') = gf(g') + f(g) \}}{\{f: G \to M : \exists m\, \forall g, \; f(g) = gm-m\}}

准此要领，亦有

H^2(G,M) = \dfrac{\{ f: G^2 \to M |  gf(g',g'')-f(gg',g'') + f(g,g'g'') - f(g,g')=0 \}}{\{ f: G^2 \to M : \exists h: G \to M, f(g,g')=gh(g')-h(gg')+h(g) \}}

#include <iostream>
#include <algorithm>
#include <vector>
using namespace std;

template<typename T>
vector<T>& operator<<(vector<T>& vi, vector<T>& vx) { //串接陣列
	int len = vi.size();
	vi.resize(vi.size() + vx.size());
	for (int i = 0; i < (int) vx.size(); i++)
		vi[i + len] = vx[i];
	return vi;
}
template<typename T>
void reverse(vector<T>& arr) { //陣列反序
	int len = arr.size();
	for (int i = 0; i < len - 1 - i; i++)
		swap(arr[i], arr[len - 1 - i]);
}

template<typename T>
void patience_sort(vector<T>& arr) {
	int len = arr.size();
	if (len < 2)
		return;
	vector<vector<T> > piles;
	for (int i = 0; i < len; i++) { //將陣列元素分堆
		vector<T> new_pile = { arr[i] };
		int insert;
		for (insert = 0; insert < (int) piles.size(); insert++) //計算目前元素比多少個堆陣列第一個元素還大
			if (new_pile[0] < piles[insert][0])
				break;
		if (insert == (int) piles.size())
			piles.push_back(new_pile);
		else
			piles[insert].push_back(arr[i]);
	}
	arr.clear();
	for (int j = 0; j < (int) piles.size(); j++) {
		reverse(piles[j]); //因為排出來的堆陣列第一個元素是該陣列最大值，故要反序
		patience_sort(piles[j]);
		arr << piles[j]; //串接陣列
	}
}

template<typename T>
ostream& operator<<(ostream& os, vector<T> v) { //顯示陣列內容
	int len = v.size();
	for (int i = 0; i < len; cout << (++i == len ? "" : ","))
		os << v[i];
	return os;
}

int main() {
	vector<int> arr = { 3, 5, 3, 0, 8, 6, 1, 5, 8, 6, 2, 4, 9, 4, 7, 0, 1, 8, 9, 7, 3, 1, 2, 5, 9, 7, 4, 0, 2, 6 };
	cout << arr << endl;
	patience_sort(arr);
	cout << arr << endl;
	return 0;
}

def to_piles(arr: list) -> list:
    if len(arr) == 1:
        return arr

    piles: list = []
    for a in arr:
        if not piles:
            piles.append([a])
            continue

        for pile in piles:
            if pile[0] > a:
                pile.append(a)
                break
        else:
            piles.append([a])

    return piles

def patience_sort(arr: list):
    piles: list = to_piles(arr)
    is_sorted: bool = True
    while is_sorted:
        temp_piles: list = []
        is_sorted = False

        for pile in piles:
            if len(pile) == 1:
                temp_piles.append(pile)
                continue

            is_sorted = True
            pile.reverse()
            temp_piles += to_piles(pile)

        piles.clear()
        piles += temp_piles

    arr.clear()
    arr += [pile[0] for pile in piles]

if __name__ == '__main__':
    arr = [3, 7, 5, 1, 3, 6, 4, 0, 8, 2]
    patience_sort(arr)
    print(arr)

